// SENSEX 1-MINUTE V2
// Rules:
// EMA 9/15 crossover
// Previous EMA trend must agree
// Range breakout
// Sideways filter using ATR
// No fixed 09:30 entry restriction
// Entries allowed after market open
// Max trades/day handled in Position State

const input = $input.all();

if (input.length === 0) {
  throw new Error("No input data received.");
}

let raw = input.map(item => item.json);

// Handle different Angel One response formats
if (raw.length === 1 && typeof raw[0] === "string") {
  raw = JSON.parse(raw[0]);
}

if (raw.length === 1 && Array.isArray(raw[0])) {
  raw = raw[0];
}

if (raw.length === 1 && raw[0] && Array.isArray(raw[0].data)) {
  raw = raw[0].data;
}

if (
  raw.length === 1 &&
  raw[0] &&
  raw[0].body &&
  Array.isArray(raw[0].body.data)
) {
  raw = raw[0].body.data;
}

// Convert candles
let candles = [];

if (raw.length > 0 && Array.isArray(raw[0])) {

  candles = raw.map(c => ({
    timestamp: c[0],
    open: Number(c[1]),
    high: Number(c[2]),
    low: Number(c[3]),
    close: Number(c[4]),
    volume: Number(c[5] || 0)
  }));

} else {

  candles = raw.map(c => ({
    timestamp: c.timestamp,
    open: Number(c.open),
    high: Number(c.high),
    low: Number(c.low),
    close: Number(c.close),
    volume: Number(c.volume || 0)
  }));

}

candles = candles.filter(c =>
  c.timestamp &&
  Number.isFinite(c.open) &&
  Number.isFinite(c.high) &&
  Number.isFinite(c.low) &&
  Number.isFinite(c.close)
);

if (candles.length === 0) {
  throw new Error("No valid candles found.");
}

candles.sort(
  (a, b) => new Date(a.timestamp) - new Date(b.timestamp)
);


// ===============================
// EMA FUNCTION
// ===============================

function calculateEMA(values, period) {

  const ema = [];
  const multiplier = 2 / (period + 1);

  let previousEMA = null;

  for (let i = 0; i < values.length; i++) {

    const price = values[i];

    if (i === period - 1) {

      const firstValues = values.slice(0, period);

      const sma =
        firstValues.reduce((sum, value) => sum + value, 0) /
        period;

      previousEMA = sma;

      ema.push(sma);

    } else if (i >= period) {

      const currentEMA =
        (price - previousEMA) * multiplier +
        previousEMA;

      previousEMA = currentEMA;

      ema.push(currentEMA);

    } else {

      ema.push(null);

    }
  }

  return ema;
}


// ===============================
// ATR 14
// ===============================

function calculateATR(candles, period = 14) {

  const tr = new Array(candles.length).fill(null);

  for (let i = 0; i < candles.length; i++) {

    if (i === 0) {

      tr[i] = candles[i].high - candles[i].low;

    } else {

      const high = candles[i].high;
      const low = candles[i].low;
      const previousClose = candles[i - 1].close;

      tr[i] = Math.max(
        high - low,
        Math.abs(high - previousClose),
        Math.abs(low - previousClose)
      );
    }
  }

  const atr = new Array(candles.length).fill(null);

  for (let i = period - 1; i < candles.length; i++) {

    const values = tr.slice(i - period + 1, i + 1);

    atr[i] =
      values.reduce((sum, value) => sum + value, 0) /
      period;
  }

  return atr;
}


const closes = candles.map(c => c.close);

const ema9 = calculateEMA(closes, 9);
const ema15 = calculateEMA(closes, 15);

const atr14 = calculateATR(candles, 14);


// ===============================
// IST TIME
// ===============================

function getIST(dateString) {

  return new Date(dateString).toLocaleString(
    "en-IN",
    {
      timeZone: "Asia/Kolkata",
      hour12: false,
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit"
    }
  );
}


// ===============================
// OUTPUT
// ===============================

const output = [];

for (let i = 0; i < candles.length; i++) {

  const candle = candles[i];

  let signal = "NONE";
  let reason = "No valid setup";

  const ist = getIST(candle.timestamp);

  // Format:
  // DD/MM/YYYY, HH:MM
  const parts = ist.split(", ");

  const datePart = parts[0];
  const timePart = parts[1];

  const [day, month, year] = datePart.split("/");

  const [hour, minute] = timePart.split(":");

  const currentMinutes =
    Number(hour) * 60 + Number(minute);


  // Market session
  const marketOpen = 9 * 60 + 15;
  const marketClose = 15 * 60 + 30;

  const entryCutoff = 14 * 60 + 30;

  const entryAllowed =
    currentMinutes >= marketOpen &&
    currentMinutes < entryCutoff &&
    currentMinutes < marketClose;


  // Need enough candles
  const enoughData =
    i >= 15;


  // ===============================
  // PREVIOUS EMA TREND
  // ===============================

  let bullishPreviousTrend = false;
  let bearishPreviousTrend = false;

  if (i >= 3) {

    bullishPreviousTrend =
      ema9[i - 2] !== null &&
      ema9[i - 3] !== null &&
      ema9[i - 2] > ema9[i - 3];

    bearishPreviousTrend =
      ema9[i - 2] !== null &&
      ema9[i - 3] !== null &&
      ema9[i - 2] < ema9[i - 3];
  }


  // ===============================
  // FRESH EMA CROSS
  // ===============================

  let bullishCross = false;
  let bearishCross = false;

  if (i >= 1) {

    bullishCross =
      ema9[i - 1] !== null &&
      ema15[i - 1] !== null &&
      ema9[i] !== null &&
      ema15[i] !== null &&
      ema9[i - 1] <= ema15[i - 1] &&
      ema9[i] > ema15[i];

    bearishCross =
      ema9[i - 1] !== null &&
      ema15[i - 1] !== null &&
      ema9[i] !== null &&
      ema15[i] !== null &&
      ema9[i - 1] >= ema15[i - 1] &&
      ema9[i] < ema15[i];
  }


  // ===============================
  // CROSSOVER RECENT WINDOW
  // Current candle OR previous 2 candles
  // ===============================

  let recentBullishCross = false;
  let recentBearishCross = false;

  for (let j = 0; j <= 2; j++) {

    const k = i - j;

    if (k < 1) continue;

    const bull =
      ema9[k - 1] !== null &&
      ema15[k - 1] !== null &&
      ema9[k] !== null &&
      ema15[k] !== null &&
      ema9[k - 1] <= ema15[k - 1] &&
      ema9[k] > ema15[k];

    const bear =
      ema9[k - 1] !== null &&
      ema15[k - 1] !== null &&
      ema9[k] !== null &&
      ema15[k] !== null &&
      ema9[k - 1] >= ema15[k - 1] &&
      ema9[k] < ema15[k];

    if (bull) recentBullishCross = true;
    if (bear) recentBearishCross = true;
  }


  // ===============================
  // SIDEWAYS FILTER
  // ===============================

  let trending = false;
  let emaSeparation = null;

  if (
    ema9[i] !== null &&
    ema15[i] !== null &&
    atr14[i] !== null
  ) {

    emaSeparation =
      Math.abs(ema9[i] - ema15[i]);

    // Same V2 rule
    trending =
      emaSeparation >= atr14[i] * 0.15;
  }


  // ===============================
  // PREVIOUS 10 CANDLE RANGE
  // ===============================

  let previousRangeHigh = null;
  let previousRangeLow = null;

  if (i >= 10) {

    const previousCandles =
      candles.slice(i - 10, i);

    previousRangeHigh =
      Math.max(...previousCandles.map(c => c.high));

    previousRangeLow =
      Math.min(...previousCandles.map(c => c.low));
  }


  const bullishBreakout =
    previousRangeHigh !== null &&
    candle.close > previousRangeHigh;

  const bearishBreakout =
    previousRangeLow !== null &&
    candle.close < previousRangeLow;


  // ===============================
  // FINAL BUY
  // ===============================

  const buySetup =
    enoughData &&
    entryAllowed &&
    recentBullishCross &&
    bullishPreviousTrend &&
    trending &&
    bullishBreakout &&
    ema9[i] !== null &&
    ema15[i] !== null &&
    ema9[i] > ema15[i] &&
    candle.close > ema9[i];


  // ===============================
  // FINAL SELL
  // ===============================

  const sellSetup =
    enoughData &&
    entryAllowed &&
    recentBearishCross &&
    bearishPreviousTrend &&
    trending &&
    bearishBreakout &&
    ema9[i] !== null &&
    ema15[i] !== null &&
    ema9[i] < ema15[i] &&
    candle.close < ema9[i];


  if (buySetup) {

    signal = "BUY";

    reason =
      "EMA9 bullish crossover + previous EMA trend + range breakout + non-sideways";

  } else if (sellSetup) {

    signal = "SELL";

    reason =
      "EMA9 bearish crossover + previous EMA trend + range breakout + non-sideways";
  }


  output.push({
    json: {

      timestamp: candle.timestamp,

      Date: `${year}-${month}-${day}`,

      Time: timePart,

      open: candle.open,
      high: candle.high,
      low: candle.low,
      close: candle.close,
      volume: candle.volume,

      EMA_9:
        ema9[i] !== null
          ? Number(ema9[i].toFixed(2))
          : null,

      EMA_15:
        ema15[i] !== null
          ? Number(ema15[i].toFixed(2))
          : null,

      ATR_14:
        atr14[i] !== null
          ? Number(atr14[i].toFixed(2))
          : null,

      EMA_Separation:
        emaSeparation !== null
          ? Number(emaSeparation.toFixed(2))
          : null,

      Previous_Range_High:
        previousRangeHigh !== null
          ? Number(previousRangeHigh.toFixed(2))
          : null,

      Previous_Range_Low:
        previousRangeLow !== null
          ? Number(previousRangeLow.toFixed(2))
          : null,

      Previous_EMA_Trend:
        bullishPreviousTrend
          ? "BULLISH"
          : bearishPreviousTrend
          ? "BEARISH"
          : "NONE",

      Bullish_Breakout:
        bullishBreakout,

      Bearish_Breakout:
        bearishBreakout,

      Trending:
        trending,

      Signal:
        signal,

      Signal_Reason:
        reason
    }
  });
}

return output;

const items = $input.all();

if (items.length === 0) {
  throw new Error("No candle data received");
}

// Read candles from previous node
const candles = items.map(item => item.json);

if (candles.length < 15) {
  throw new Error("At least 15 candles are required for ATR(14)");
}

// Calculate True Range
const trueRanges = candles.map((candle, i) => {
  const high = Number(candle.high);
  const low = Number(candle.low);

  if (i === 0) {
    return high - low;
  }

  const previousClose = Number(candles[i - 1].close);

  return Math.max(
    high - low,
    Math.abs(high - previousClose),
    Math.abs(low - previousClose)
  );
});

// ATR(14) using Wilder's smoothing
const period = 14;
const atr = new Array(candles.length).fill(null);

// First ATR = SMA of first 14 TR values
let trSum = 0;

for (let i = 1; i <= period; i++) {
  trSum += trueRanges[i];
}

atr[period] = trSum / period;

// Subsequent ATR values using Wilder smoothing
for (let i = period + 1; i < candles.length; i++) {
  atr[i] =
    ((atr[i - 1] * (period - 1)) + trueRanges[i]) / period;
}

// Return candles with ATR
return candles.map((candle, i) => ({
  json: {
    ...candle,
    ATR_14: atr[i]
  }
}));

const items = $input.all();

if (items.length < 3) {
  throw new Error("At least 3 candles are required");
}

const candles = items.map(item => item.json);

const output = candles.map((candle, i) => {
  let structure = "NONE";

  if (i >= 2) {
    const prev = candles[i - 1];
    const prev2 = candles[i - 2];

    const high = Number(candle.high);
    const low = Number(candle.low);

    const prevHigh = Number(prev.high);
    const prevLow = Number(prev.low);

    const prev2High = Number(prev2.high);
    const prev2Low = Number(prev2.low);

    // Higher High
    if (high > prevHigh && prevHigh > prev2High) {
      structure = "HH";
    }

    // Higher Low
    else if (low > prevLow && prevLow > prev2Low) {
      structure = "HL";
    }

    // Lower High
    else if (high < prevHigh && prevHigh < prev2High) {
      structure = "LH";
    }

    // Lower Low
    else if (low < prevLow && prevLow < prev2Low) {
      structure = "LL";
    }
  }

  return {
    json: {
      ...candle,
      Structure: structure
    }
  };
});

return output;

const items = $input.all();

if (items.length === 0) {
  throw new Error("No candles received");
}

const candles = items.map(item => item.json);

// Find recent HH and LL
let swingHigh = null;
let swingLow = null;
let swingHighIndex = -1;
let swingLowIndex = -1;

for (let i = candles.length - 1; i >= 0; i--) {

  const high = Number(candles[i].high);
  const low = Number(candles[i].low);

  if (
    swingHigh === null &&
    candles[i].Structure === "HH" &&
    Number.isFinite(high)
  ) {
    swingHigh = high;
    swingHighIndex = i;
  }

  if (
    swingLow === null &&
    candles[i].Structure === "LL" &&
    Number.isFinite(low)
  ) {
    swingLow = low;
    swingLowIndex = i;
  }

  if (swingHigh !== null && swingLow !== null) {
    break;
  }
}

// Default Fibonacci values
let fibValues = {
  Fib_Swing_High: null,
  Fib_Swing_Low: null,
  Fib_0: null,
  Fib_23_6: null,
  Fib_38_2: null,
  Fib_50: null,
  Fib_61_8: null,
  Fib_78_6: null,
  Fib_100: null
};

// Calculate Fibonacci only when the range is valid
if (
  swingHigh !== null &&
  swingLow !== null &&
  swingHigh > swingLow
) {

  const range = swingHigh - swingLow;

  fibValues = {
    Fib_Swing_High: swingHigh,
    Fib_Swing_Low: swingLow,

    Fib_0: swingLow,
    Fib_23_6: swingLow + range * 0.236,
    Fib_38_2: swingLow + range * 0.382,
    Fib_50: swingLow + range * 0.500,
    Fib_61_8: swingLow + range * 0.618,
    Fib_78_6: swingLow + range * 0.786,
    Fib_100: swingHigh
  };
}

return candles.map(candle => ({
  json: {
    ...candle,

    ...fibValues
  }
}));

const items = $input.all();

if (items.length === 0) {
  throw new Error("No candle data received.");
}

const SL_POINTS = 30;
const TP_POINTS = 60;

return items.map(item => {

  const candle = item.json;

  const close = Number(candle.close);

  const crossoverSignal =
    String(candle.Signal || "NONE").toUpperCase();

  let signal = "HOLD";

  let stopLoss = null;
  let target = null;

  if (
    Number.isFinite(close) &&
    (crossoverSignal === "BUY" ||
     crossoverSignal === "SELL")
  ) {

    signal = crossoverSignal;
  }


  if (signal === "BUY") {

    stopLoss = close - SL_POINTS;
    target = close + TP_POINTS;

  } else if (signal === "SELL") {

    stopLoss = close + SL_POINTS;
    target = close - TP_POINTS;
  }


  return {
    json: {

      ...candle,

      Index: "SENSEX",

      Strategy_Signal: signal,

      Signal_Reason:
        candle.Signal_Reason || "No setup",

      Entry_Price:
        signal !== "HOLD"
          ? Number(close.toFixed(2))
          : null,

      Initial_SL:
        stopLoss !== null
          ? Number(stopLoss.toFixed(2))
          : null,

      Target:
        target !== null
          ? Number(target.toFixed(2))
          : null,

      SL_Points:
        signal !== "HOLD"
          ? SL_POINTS
          : null,

      TP_Points:
        signal !== "HOLD"
          ? TP_POINTS
          : null,

      EMA_Crossover:
        crossoverSignal
    }
  };
});

// ============================================
// SENSEX 1-MINUTE PAPER TRADING V2
// ============================================
//
// SL = 30 points
// TP = 60 points
// EMA9 trailing activates after +30 points
// Maximum 2 trades per day
// No real Angel One orders
//
// BACKTEST_MODE = true
// means every historical test starts fresh.
//
// Before live paper trading:
// change BACKTEST_MODE = false
// ============================================


const BACKTEST_MODE = true;

const STATE_KEY = "paperTradeSensex1M";

const MAX_TRADES_PER_DAY = 2;

const SL_POINTS = 30;

const TP_POINTS = 60;

const TRAIL_ACTIVATION = 30;


// ============================================
// INPUT
// ============================================

const items = $input.all();

if (items.length === 0) {
  throw new Error("No input data.");
}


// ============================================
// STATIC STATE
// ============================================

const staticData = $getWorkflowStaticData("global");

let state;

if (BACKTEST_MODE) {

  // Fresh state every historical test
  state = {
    position: null,
    tradesToday: 0,
    currentDate: null
  };

} else {

  if (!staticData[STATE_KEY]) {

    staticData[STATE_KEY] = {

      position: null,

      tradesToday: 0,

      currentDate: null
    };
  }

  state = staticData[STATE_KEY];
}


// ============================================
// HELPERS
// ============================================

function getISTParts(timestamp) {

  const ist =
    new Date(timestamp).toLocaleString(
      "en-IN",
      {
        timeZone: "Asia/Kolkata",
        hour12: false,
        year: "numeric",
        month: "2-digit",
        day: "2-digit",
        hour: "2-digit",
        minute: "2-digit"
      }
    );

  const [datePart, timePart] =
    ist.split(", ");

  const [day, month, year] =
    datePart.split("/");

  return {
    date: `${year}-${month}-${day}`,
    time: timePart
  };
}


// ============================================
// SORT CANDLES
// ============================================

const candles = items
  .map(item => item.json)
  .sort(
    (a, b) =>
      new Date(a.timestamp) -
      new Date(b.timestamp)
  );


// ============================================
// OUTPUT ONLY COMPLETED TRADES
// ============================================

const completedTrades = [];


// ============================================
// PROCESS CANDLES
// ============================================

for (let i = 0; i < candles.length; i++) {

  const candle = candles[i];

  const close = Number(candle.close);
  const high = Number(candle.high);
  const low = Number(candle.low);

  const ema9 = Number(candle.EMA_9);

  const signal =
    String(
      candle.Strategy_Signal || "HOLD"
    ).toUpperCase();

  const {
    date: currentDate,
    time: currentTime
  } = getISTParts(candle.timestamp);


  // ========================================
  // NEW DAY
  // ========================================

  if (
    state.currentDate !== null &&
    state.currentDate !== currentDate
  ) {

    // Safety: close any remaining position
    // at previous candle close.
    if (state.position !== null) {

      const position = state.position;

      const exitPrice = close;

      let gainPoints;

      if (position.side === "BUY") {

        gainPoints =
          exitPrice - position.entry;

      } else {

        gainPoints =
          position.entry - exitPrice;
      }

      completedTrades.push({

        Date: position.date,

        Time: currentTime,

        Index: "SENSEX",

        Entry: Number(
          position.entry.toFixed(2)
        ),

        Exit: Number(
          exitPrice.toFixed(2)
        ),

        SL: Number(
          position.sl.toFixed(2)
        ),

        TP: Number(
          position.tp.toFixed(2)
        ),

        "EMA Crossover":
          position.emaCrossover,

        Gain_Points:
          Number(gainPoints.toFixed(2)),

        Exit_Reason:
          "DAY_CHANGE",

        Result:
          gainPoints >= 0
            ? "WIN"
            : "LOSS"
      });

      state.position = null;
    }

    state.tradesToday = 0;
  }

  state.currentDate = currentDate;


  // ========================================
  // IF POSITION EXISTS
  // ========================================

  if (state.position !== null) {

    const position = state.position;

    let exitPrice = null;

    let exitReason = null;


    // ======================================
    // UPDATE EXTREME PRICE
    // ======================================

    if (position.side === "BUY") {

      if (high > position.highestPrice) {

        position.highestPrice = high;
      }

    } else {

      if (low < position.lowestPrice) {

        position.lowestPrice = low;
      }
    }


    // ======================================
    // FIXED SL
    // ======================================

    if (position.side === "BUY") {

      if (low <= position.sl) {

        exitPrice = position.sl;

        exitReason = "STOP_LOSS";
      }

    } else {

      if (high >= position.sl) {

        exitPrice = position.sl;

        exitReason = "STOP_LOSS";
      }
    }


    // ======================================
    // FIXED TP
    // ======================================

    if (exitPrice === null) {

      if (position.side === "BUY") {

        if (high >= position.tp) {

          exitPrice = position.tp;

          exitReason = "TARGET_60";
        }

      } else {

        if (low <= position.tp) {

          exitPrice = position.tp;

          exitReason = "TARGET_60";
        }
      }
    }


    // ======================================
    // EMA9 TRAILING
    // Activates after +30 points
    // ======================================

    if (
      exitPrice === null &&
      position.trailingActive === true &&
      Number.isFinite(ema9)
    ) {

      if (
        position.side === "BUY" &&
        close < ema9
      ) {

        exitPrice = close;

        exitReason = "EMA9_TRAILING";
      }

      if (
        position.side === "SELL" &&
        close > ema9
      ) {

        exitPrice = close;

        exitReason = "EMA9_TRAILING";
      }
    }


    // ======================================
    // ACTIVATE TRAILING
    // ======================================

    if (exitPrice === null) {

      if (position.side === "BUY") {

        const profit =
          high - position.entry;

        if (profit >= TRAIL_ACTIVATION) {

          position.trailingActive = true;
        }

      } else {

        const profit =
          position.entry - low;

        if (profit >= TRAIL_ACTIVATION) {

          position.trailingActive = true;
        }
      }
    }


    // ======================================
    // END OF DAY
    // ======================================

    const nextCandle =
      candles[i + 1];

    let isLastCandleOfDay = false;

    if (!nextCandle) {

      isLastCandleOfDay = true;

    } else {

      const nextDate =
        getISTParts(
          nextCandle.timestamp
        ).date;

      if (nextDate !== currentDate) {

        isLastCandleOfDay = true;
      }
    }


    if (
      exitPrice === null &&
      isLastCandleOfDay
    ) {

      exitPrice = close;

      exitReason = "END_OF_DAY";
    }


    // ======================================
    // CLOSE TRADE
    // ======================================

    if (exitPrice !== null) {

      let gainPoints;

      if (position.side === "BUY") {

        gainPoints =
          exitPrice - position.entry;

      } else {

        gainPoints =
          position.entry - exitPrice;
      }


      completedTrades.push({

        Date: position.date,

        Time: currentTime,

        Index: "SENSEX",

        Entry: Number(
          position.entry.toFixed(2)
        ),

        Exit: Number(
          exitPrice.toFixed(2)
        ),

        SL: Number(
          position.sl.toFixed(2)
        ),

        TP: Number(
          position.tp.toFixed(2)
        ),

        "EMA Crossover":
          position.emaCrossover,

        Gain_Points:
          Number(
            gainPoints.toFixed(2)
          ),

        Exit_Reason:
          exitReason,

        Result:
          gainPoints >= 0
            ? "WIN"
            : "LOSS"
      });


      state.position = null;

    }


    // ======================================
    // IMPORTANT:
    // Don't open another trade on the same
    // candle after closing.
    // ======================================

    continue;
  }


  // ========================================
  // NO POSITION
  // CHECK ENTRY
  // ========================================

  if (signal !== "BUY" && signal !== "SELL") {

    continue;
  }


  // ========================================
  // MAX 2 TRADES / DAY
  // ========================================

  if (
    state.tradesToday >= MAX_TRADES_PER_DAY
  ) {

    continue;
  }


  // ========================================
  // ENTRY
  // ========================================

  const entryPrice = close;

  let sl;

  let tp;


  if (signal === "BUY") {

    sl = entryPrice - SL_POINTS;

    tp = entryPrice + TP_POINTS;

  } else {

    sl = entryPrice + SL_POINTS;

    tp = entryPrice - TP_POINTS;
  }


  state.position = {

    side: signal,

    entry: entryPrice,

    sl: sl,

    tp: tp,

    date: currentDate,

    entryTime: currentTime,

    emaCrossover:
      String(
        candle.EMA_Crossover || signal
      ),

    trailingActive: false,

    highestPrice: entryPrice,

    lowestPrice: entryPrice
  };


  state.tradesToday++;


  // Don't process SL/TP on the same candle
  // on which the position was opened.
  continue;
}


// ============================================
// SAVE LIVE STATE
// ============================================

if (!BACKTEST_MODE) {

  staticData[STATE_KEY] = state;
}


// ============================================
// RETURN COMPLETED TRADES
// ============================================

return completedTrades.map(trade => ({

  json: {

    Date: trade.Date,

    Time: trade.Time,

    Index: trade.Index,

    Entry: trade.Entry,

    Exit: trade.Exit,

    SL: trade.SL,

    TP: trade.TP,

    "EMA Crossover":
      trade["EMA Crossover"],

    Gain_Points:
      trade.Gain_Points,

    Exit_Reason:
      trade.Exit_Reason,

    Result:
      trade.Result
  }

}));

const crypto = require('crypto');

const secret = $env.ANGELONE_TOTP_SECRET;

if (!secret) {
  throw new Error('ANGELONE_TOTP_SECRET is not configured');
}

function base32ToBuffer(base32) {
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
  const cleaned = base32.toUpperCase().replace(/[\s=]/g, '');

  let bits = '';

  for (const char of cleaned) {
    const value = alphabet.indexOf(char);

    if (value === -1) {
      throw new Error('Invalid Base32 TOTP secret');
    }

    bits += value.toString(2).padStart(5, '0');
  }

  const bytes = [];

  for (let i = 0; i + 8 <= bits.length; i += 8) {
    bytes.push(parseInt(bits.substring(i, i + 8), 2));
  }

  return Buffer.from(bytes);
}

function generateTOTP(secret, timestamp) {
  const key = base32ToBuffer(secret);

  const counter = Math.floor(timestamp / 1000 / 30);

  const counterBuffer = Buffer.alloc(8);

  counterBuffer.writeUInt32BE(
    Math.floor(counter / 0x100000000),
    0
  );

  counterBuffer.writeUInt32BE(
    counter >>> 0,
    4
  );

  const hmac = crypto
    .createHmac('sha1', key)
    .update(counterBuffer)
    .digest();

  const offset = hmac[hmac.length - 1] & 0x0f;

  const binary =
    ((hmac[offset] & 0x7f) << 24) |
    ((hmac[offset + 1] & 0xff) << 16) |
    ((hmac[offset + 2] & 0xff) << 8) |
    (hmac[offset + 3] & 0xff);

  return String(binary % 1000000).padStart(6, '0');
}

const now = Date.now();

const secondsIntoPeriod = Math.floor(now / 1000) % 30;
const secondsRemaining = 30 - secondsIntoPeriod;

return [
  {
    json: {
      totp: generateTOTP(secret, now),
      secondsRemaining: secondsRemaining,
      generatedAt: new Date(now).toISOString()
    }
  }
];

return [
  {
    json: {
      login_totp: String($json.totp),
      generatedAt: $json.generatedAt,
      secondsRemaining: $json.secondsRemaining
    }
  }
];
